<?php if($tahap<=2):?><div class="document-groups"><?php $groups=array('Dokumen Umum'=>array('file_ktp','file_kepemilikan_tanah','file_data_perencana','file_pernyataan_tataruang'),'Bidang Arsitektur & Tata Ruang'=>array('file_pkkpr','file_rencana_teknis','file_dokumen_lingkungan'),'Bidang Struktur'=>array('file_teknis_struktur'),'Bidang MEP'=>array('file_checklist_mep')); foreach($groups as $group=>$fields):?><section><h3><?= $group ?></h3><ul class="doc-list"><?php foreach($fields as $f): $ada=!empty($row[$f]);?><li class="<?= $ada?'ok':'missing' ?>"><span class="doc-icon"><?= $ada?'✓':'!' ?></span><span><b><?= htmlspecialchars($files[$f]) ?></b><small><?= in_array($f,$wajib,true)?'Wajib':'Opsional' ?></small></span><em><?= $ada?'Tersedia':'Belum diunggah' ?></em></li><?php endforeach;?></ul></section><?php endforeach;?></div>
<?php if(!empty($row['catatan_admin'])):?><div class="notice"><b>Catatan PU terakhir</b><br><?= nl2br(htmlspecialchars($row['catatan_admin'])) ?></div><?php endif;?>
