<?php elseif($tahap===3):?><p>PU memverifikasi hasil perbaikan dan pemeriksaan teknis dari setiap bidang.</p><div class="review-grid"><?php foreach(array('Arsitektur & Tata Ruang'=>array('file_pkkpr','file_rencana_teknis'),'Struktur'=>array('file_teknis_struktur'),'MEP'=>array('file_checklist_mep')) as $bidang=>$fields): $ok=true; foreach($fields as $f){if(empty($row[$f]))$ok=false;}?><article><span class="review-icon"><?= $ok?'✓':'!' ?></span><div><h3><?= $bidang ?></h3><p><?= $ok?'Dokumen tersedia dan siap diverifikasi.':'Dokumen bidang belum lengkap.' ?></p><span class="badge <?= $ok?'disetujui':'diajukan' ?>"><?= $ok?'Siap Diverifikasi':'Perlu Perbaikan' ?></span></div></article><?php endforeach;?></div><div class="notice"><b>Catatan PU:</b><br><?= nl2br(htmlspecialchars($row['catatan_admin']?:'Belum ada catatan.')) ?></div><div class="decision-actions"><?= form_open('pengajuan-pbg/ubah-tahap/'.$row['id']) ?><input type="hidden" name="tahap" value="4"><input type="hidden" name="status" value="disetujui"><button class="btn btn-primary">Proses Selesai</button><?= form_close() ?><button class="btn note-toggle" type="button">Perlu Perbaikan</button></div><div class="note-panel" hidden><?= form_open('pengajuan-pbg/ubah-tahap/'.$row['id']) ?><input type="hidden" name="tahap" value="3"><input type="hidden" name="status" value="diverifikasi"><label>Catatan hasil verifikasi</label><textarea name="catatan" required></textarea><button class="btn" style="margin-top:10px">Simpan Catatan</button><?= form_close() ?></div>
